#!/usr/bin/env node
//
// Writes theme-creator.html — Phase 14 (roadmap §4.14). Generated and
// committed like kitchen-sink.html, portal.html and builder.html, for the
// same reason: everything on it derives from files on disk, and a
// hand-maintained copy would drift. `npm run theme-creator`; regenerated by
// `npm run verify`, right after `npm run theme-families` writes the
// catalogue this reads.
//
// WHAT THE PAGE IS. Twenty rows, one per `--rux-*` interactive-family token
// in css/rux-theme.css, each a hex field with a live swatch and a contrast
// readout for every scenario theme-creator/scenarios.json records that
// token against. A family select above the rows sets all twenty from one of
// Carbon's own hue ramps in a single action (theme-creator/families.json,
// written by tools/build-theme-families.mjs from @carbon/colors). No
// stepper, no guided/free split: unlike the page builder this composes
// nothing from parts, so there is one screen, not a sequence.
//
// THE TWENTY ROWS ARE STATIC MARKUP, not cloned at runtime. Builder.html
// clones because its blocks are a variable, per-template catalogue; this
// page's twenty tokens and their scenarios are fixed by scenarios.json at
// build time, so the rows themselves — label, hex input, swatch, one badge
// per scenario — are written here where check-classes can read them, and
// theme-creator.js only ever fills in values and badge text/state.
//
// DEFAULTS COME FROM css/rux-theme.css ITSELF, read and embedded as JSON
// below, so the fine-tune fields always seed from whatever that file
// currently says rather than a second, hand-kept copy that could drift from
// it silently.
//
// THE PREVIEW IS OUTSIDE EVERY GATE, same as builder.html's: check-a11y and
// the rest query the top document and do not descend into an iframe.
//
// THE CHROME IS thc-. Layout this page needs beyond compiled components is
// an inline <style> on --rux-* tokens with thc- classes, ignored by
// check-classes exactly as bld- and the sink's ks- are, and read by
// check-tokens because this is a root page.
import { readFileSync, writeFileSync } from 'node:fs';

const sprite = readFileSync('assets/icons.svg', 'utf8').trim();
const symbols = new Set([...sprite.matchAll(/<symbol\s+id="([^"]+)"/g)].map(m => m[1]));

const { families } = JSON.parse(readFileSync('theme-creator/families.json', 'utf8'));
const { scenarios } = JSON.parse(readFileSync('theme-creator/scenarios.json', 'utf8'));

// The twenty tokens, in css/rux-theme.css's own order, each named the
// Carbon shade key theme-creator/theme-creator.js reads out of a family
// when "Apply family" runs — roadmap §4.14's Step 2 table, not re-derived
// here: a mismatch between this list and that table is a build that still
// succeeds but applies the wrong shade, so it is asserted against
// css/rux-theme.css's own token names below rather than trusted silently.
const TOKENS = [
  ['interactive', 'Interactive', '60'],
  ['icon-interactive', 'Icon (interactive)', '60'],
  ['border-interactive', 'Border (interactive)', '60'],
  ['background-brand', 'Background (brand)', '60'],
  ['focus', 'Focus ring', '60'],
  ['highlight', 'Highlight', '20'],
  ['link-primary', 'Link', '60'],
  ['link-primary-hover', 'Link (hover)', '70'],
  ['link-secondary', 'Link (secondary)', '70'],
  ['link-inverse', 'Link (on an inverse surface)', '40'],
  ['link-inverse-hover', 'Link (on an inverse surface, hover)', '30'],
  ['button-primary', 'Button, primary', '60'],
  ['button-primary-hover', 'Button, primary (hover)', '70Hover'],
  ['button-primary-active', 'Button, primary (active)', '80'],
  ['button-tertiary', 'Button, tertiary', '60'],
  ['button-tertiary-hover', 'Button, tertiary (hover)', '70Hover'],
  ['button-tertiary-active', 'Button, tertiary (active)', '80'],
  ['chat-button', 'Chat button', '60'],
  ['chat-button-text-hover', 'Chat button text (hover)', '70'],
  ['chat-avatar-user', 'Chat avatar (user)', '60'],
];

// css/rux-theme.css's own [data-theme="rux"] block is the one source of
// truth for today's values — read directly, not retyped, so this page can
// never disagree with the file it exists to help someone replace.
const themeCss = readFileSync('css/rux-theme.css', 'utf8');
const block = themeCss.match(/\[data-theme="rux"\]\s*\{([\s\S]*?)\n\}/);
if (!block) { console.log('  build-theme-creator: no [data-theme="rux"] block in css/rux-theme.css'); process.exit(1); }
const DEFAULTS = {};
for (const m of block[1].matchAll(/--rux-([a-z-]+):\s*(#[0-9a-f]{3,8});/gi)) DEFAULTS[m[1]] = m[2];
for (const [name] of TOKENS) {
  if (!(name in DEFAULTS)) { console.log(`  build-theme-creator: css/rux-theme.css has no --rux-${name}, but TOKENS names it`); process.exit(1); }
}

const TEMPLATES = ['app-shell', 'dashboard-page', 'detail-page', 'empty-state', 'error-state', 'form-page', 'schedule-page', 'settings-page', 'table-page', 'wizard-page'];
const WIDTHS = [['375', '375'], ['672', '672'], ['1056', '1056'], ['1280', '1280'], ['1440', '1440'], ['fit', 'Fit']];
const esc = t => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const familyOptions = Object.keys(families).sort()
  .map(name => `          <option value="${name}">${esc(name[0].toUpperCase() + name.slice(1))}</option>`).join('\n');

const targetOptions = [`          <option value="kitchen-sink.html">Kitchen sink</option>`]
  .concat(TEMPLATES.map(t => `          <option value="templates/${t}.html">${esc(t)}</option>`)).join('\n');

// One row per token: the hex field, a swatch the script paints, and one
// badge per scenario scenarios.json records for it — label and threshold
// are static (attested data), the ratio and pass/warn state are the only
// thing theme-creator.js ever writes into a badge.
const rows = TOKENS.map(([name, label]) => {
  const own = scenarios.filter(s => s.token === name);
  const badges = own.map((s, i) => `
        <span class="thc-badge" data-token="${name}" data-scenario="${own.indexOf(s)}" data-threshold="${s.threshold}" title="${esc(s.note)}">${esc(s.state)} — checking…</span>`).join('');
  return `
      <div class="thc-row" data-token="${name}">
        <div class="thc-row__field">
          <div class="rux--form-item rux--text-input-wrapper">
            <div class="rux--text-input__label-wrapper">
              <label class="rux--label" for="thc-tok-${name}">${esc(label)}</label>
            </div>
            <div class="rux--text-input__field-outer-wrapper">
              <div class="rux--text-input__field-wrapper">
                <input id="thc-tok-${name}" class="rux--text-input" type="text" inputmode="text" value="${DEFAULTS[name]}" data-token="${name}">
              </div>
            </div>
          </div>
          <span class="thc-swatch" id="thc-swatch-${name}" aria-hidden="true"></span>
        </div>
        <div class="thc-row__badges">${badges || '<span class="thc-status">not read against a scenario</span>'}</div>
      </div>`;
}).join('\n');

const page = `<!doctype html>
<html lang="en" data-theme="white">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>rux-ds — theme creator</title>
<link rel="icon" href="brand/favicon.svg" type="image/svg+xml">
<link rel="preload" as="font" type="font/woff2" crossorigin href="assets/fonts/IBMPlexSans-Regular-Latin1.woff2">
<link rel="preload" as="font" type="font/woff2" crossorigin href="assets/fonts/IBMPlexSans-SemiBold-Latin1.woff2">
<link rel="stylesheet" href="assets/fonts/plex.css">
<link rel="stylesheet" href="css/rux.css">
<link rel="stylesheet" href="css/rux-theme.css">
<link rel="stylesheet" href="css/rux-overrides.css">
<script src="js/theme.js"></script>
<style>
/* The theme creator's own layout, thc- so check-classes ignores it the way
   it ignores the builder's bld- and the sink's ks-. Tokens only. */
.thc-preview { background: var(--rux-layer-01); border: 1px solid var(--rux-border-subtle-01); padding: var(--rux-spacing-05); overflow: auto; }
.thc-frame-wrap { transform-origin: top left; }
.thc-frame { display: block; inline-size: 100%; block-size: 48rem; border: 0; background: var(--rux-background); }
.thc-widths, .thc-row-group { display: flex; flex-wrap: wrap; gap: var(--rux-spacing-03); }
.thc-status { color: var(--rux-text-secondary); }
.thc-row { display: flex; flex-direction: column; gap: var(--rux-spacing-02); padding-block: var(--rux-spacing-04); border-block-end: 1px solid var(--rux-border-subtle-01); }
.thc-row__field { display: flex; align-items: flex-end; gap: var(--rux-spacing-03); }
.thc-row__badges { display: flex; flex-wrap: wrap; gap: var(--rux-spacing-03); }
.thc-swatch { display: inline-block; inline-size: 2rem; block-size: 2rem; border: 1px solid var(--rux-border-subtle-01); flex: none; }
.thc-badge { font-size: 0.75rem; padding: 0.125rem 0.5rem; border: 1px solid var(--rux-border-subtle-01); }
.thc-badge--pass { color: var(--rux-support-success); border-color: var(--rux-support-success); }
.thc-badge--warn { color: var(--rux-support-error); border-color: var(--rux-support-error); }
.thc-command { display: block; background: var(--rux-layer-01); border: 1px solid var(--rux-border-subtle-01); padding: var(--rux-spacing-03); overflow-x: auto; white-space: pre-wrap; overflow-wrap: break-word; }
/* Carbon's reset gives <section> display:block, which would beat a bare
   [hidden] on origin — the same finding builder.html and
   css/rux-overrides.css's .rux--btn[hidden] both record. Nothing on this
   page is hidden inside a <section>, but the rule travels with the class
   in case that changes; a rule that costs nothing until it is needed is
   cheaper than re-discovering the finding. */
.thc-step[hidden] { display: none; }
</style>
</head>
<body>
<!-- GENERATED by tools/build-theme-creator.mjs — do not edit. Edit the generator. -->
<!-- PROVENANCE: rendered-dom · the shell is portal.html's, header-only, from
     components-ui-shell-header--header-w-navigation-actions-and-side-nav
     captured 2026-08-31; the controls are sink/text-input.html and
     sink/select.html markup, verbatim -->
<!-- BEHAVIOUR: derived · theme-creator/theme-creator.js is rux's own, not
     Carbon's: it derives twenty token values from a Carbon hue family or
     individual hex edits, previews them on an existing page, and computes
     WCAG contrast against theme-creator/scenarios.json's named pairings.
     NOT COVERED, by construction: anything inside the preview iframe —
     check-a11y, check-spacing and check-runtime-classes read the top
     document only. The contrast readout is advisory only and is not a
     gate. -->

${sprite}

<header class="rux--header" data-theme="g100" aria-label="rux-ds">
  <a class="rux--skip-to-content" href="#main-content">Skip to main content</a>
  <a class="rux--header__name" href="theme-creator.html"><img src="brand/logo.svg" alt="" style="height:1.5rem;width:auto;margin-right:.5rem;flex:none"><span class="rux--header__name--prefix">Rux</span>&nbsp;DS</a>
  <nav class="rux--header__nav" aria-label="rux-ds">
    <ul class="rux--header__menu-bar">
      <li><a class="rux--header__menu-item" href="portal.html"><span class="rux--text-truncate-end">Portal</span></a></li>
      <li><a class="rux--header__menu-item" href="kitchen-sink.html"><span class="rux--text-truncate-end">Kitchen sink</span></a></li>
      <li><a class="rux--header__menu-item" href="builder.html"><span class="rux--text-truncate-end">Builder</span></a></li>
      <li><a class="rux--header__menu-item rux--header__menu-item--current" href="theme-creator.html" aria-current="page"><span class="rux--text-truncate-end">Theme creator</span></a></li>
    </ul>
  </nav>
</header>

<main id="main-content" class="rux--content">
  <div class="rux--css-grid">
    <div class="rux--css-grid-column rux--col-span-100">
      <div class="rux--stack-vertical rux--stack-scale-7">
        <div class="rux--stack-vertical rux--stack-scale-5">
          <h1>Theme creator</h1>
          <p>Pick a Carbon hue family or fine-tune each token by hex, watch an existing page re-render, and take the CSS block away. The contrast readout is advisory: it warns on a ratio below the threshold a token's own use calls for, and never blocks — <code>theme-creator/scenarios.json</code> says what each token is checked against and why.</p>
        </div>
        <div id="thc-notice"></div>
        <div class="rux--subgrid rux--subgrid--wide rux--subgrid--with-row-gap">

          <div class="rux--css-grid-column rux--sm:col-span-4 rux--md:col-span-8 rux--lg:col-span-5">
            <div class="rux--stack-vertical rux--stack-scale-7">
              <div class="thc-row-group" role="group" aria-label="History">
                <button type="button" class="rux--btn rux--btn--ghost rux--btn--sm rux--layout--size-sm" id="thc-undo" disabled>Undo</button>
                <button type="button" class="rux--btn rux--btn--ghost rux--btn--sm rux--layout--size-sm" id="thc-redo" disabled>Redo</button>
                <button type="button" class="rux--btn rux--btn--danger--ghost rux--btn--sm rux--layout--size-sm" id="thc-start-over">Start over</button>
              </div>

              <div class="rux--form-item rux--text-input-wrapper">
                <div class="rux--text-input__label-wrapper">
                  <label class="rux--label" for="thc-name">Theme name</label>
                </div>
                <div class="rux--text-input__field-outer-wrapper">
                  <div class="rux--text-input__field-wrapper">
                    <input id="thc-name" class="rux--text-input" type="text" value="rux" placeholder="rux">
                  </div>
                </div>
                <div class="rux--form__helper-text" id="thc-name-helper">Lowercase letters, digits and hyphens; not white, g10, g90 or g100 — those are compiled Carbon themes, not a surface to layer over.</div>
              </div>

              <div class="rux--form-item">
                <div class="rux--select">
                  <label class="rux--label" for="thc-family">Carbon hue family</label>
                  <div class="rux--select-input__wrapper">
                    <select id="thc-family" class="rux--select-input">
                      <option value="">— pick a family to set all twenty at once —</option>
${familyOptions}
                    </select>
                    <svg class="rux--select__arrow" width="16" height="16" viewBox="0 0 32 32" fill="currentColor" aria-hidden="true"><use href="#i-chevron--down"/></svg>
                  </div>
                  <div class="rux--form__helper-text">Applies the same grade-substitution the shipped <code>rux</code> theme already proves — one undoable step, overwriting all twenty fields below.</div>
                </div>
              </div>

              <h2 class="rux--type-heading-compact-01">Twenty tokens</h2>
              <div id="thc-rows">${rows}
              </div>
            </div>
          </div>

          <div class="rux--css-grid-column rux--sm:col-span-4 rux--md:col-span-8 rux--lg:col-span-11">
            <div class="rux--stack-vertical rux--stack-scale-5">
              <h2>Preview</h2>
              <div class="rux--form-item">
                <div class="rux--select">
                  <label class="rux--label" for="thc-target">Page to preview</label>
                  <div class="rux--select-input__wrapper">
                    <select id="thc-target" class="rux--select-input">
${targetOptions}
                    </select>
                    <svg class="rux--select__arrow" width="16" height="16" viewBox="0 0 32 32" fill="currentColor" aria-hidden="true"><use href="#i-chevron--down"/></svg>
                  </div>
                  <div class="rux--form__helper-text">The real page, in a frame of its own; its own account panel still opens, but its theme radios are sandboxed to this preview and never touch your actual profile.</div>
                </div>
              </div>
              <div class="thc-widths" role="group" aria-label="Preview width">
${WIDTHS.map(([v, l]) => `                <button type="button" class="rux--btn rux--btn--ghost rux--btn--sm rux--layout--size-sm" data-width="${v}" aria-pressed="${v === 'fit'}">${l}</button>`).join('\n')}
              </div>
              <p class="thc-status" id="thc-preview-status">Loading…</p>
              <div class="thc-preview">
                <div class="thc-frame-wrap" id="thc-frame-wrap">
                  <iframe class="thc-frame" id="thc-frame" title="Preview of the candidate theme"></iframe>
                </div>
              </div>

              <h2 class="rux--type-heading-compact-01">Take it away</h2>
              <p>Paste this into a project's own <code>css/rux-theme.css</code> — never written for you; this tool only ever offers text to copy.</p>
              <code class="thc-command" id="thc-export"></code>
              <div class="thc-row-group">
                <button type="button" class="rux--btn rux--btn--ghost rux--btn--sm rux--layout--size-sm" id="thc-copy">Copy the CSS block</button>
                <button type="button" class="rux--btn rux--btn--ghost rux--btn--sm rux--layout--size-sm" id="thc-download">Download rux-theme.css</button>
              </div>
            </div>
          </div>

        </div>
      </div>
    </div>
  </div>
</main>

<script src="js/overlay.js"></script>
<script src="js/popover.js"></script>
<script src="js/menu.js"></script>
<script src="js/list-box.js"></script>
<script src="js/tabs.js"></script>
<script src="js/accordion.js"></script>
<script src="js/data-table.js"></script>
<script src="js/form-controls.js"></script>
<script src="js/ui-shell.js"></script>
<script src="js/dismiss.js"></script>
<script src="js/tile.js"></script>
<script src="js/modal.js"></script>
<script type="application/json" id="thc-defaults">${JSON.stringify(DEFAULTS)}</script>
<script type="module" src="theme-creator/theme-creator.js"></script>
</body>
</html>
`;

const body = page.slice(page.indexOf('</svg>') + 6);
const missing = [...new Set([...body.matchAll(/<use\s+href="#(i-[^"]+)"/g)].map(m => m[1]))].filter(id => !symbols.has(id));
if (missing.length) {
  for (const id of missing) console.log(`  build-theme-creator: no <symbol id="${id}"> in assets/icons.svg`);
  process.exit(1);
}
writeFileSync('theme-creator.html', page);
console.log(`  theme-creator.html — ${(page.length / 1024).toFixed(0)} KB · ${symbols.size} symbols inlined`);
